// src/drift.ts
function windowStats(scores, passThreshold) {
  const n = scores.length;
  if (n === 0) {
    return { mean: 0, stddev: 0, passRate: 0, sampleSize: 0 };
  }
  const mean = scores.reduce((s, v) => s + v, 0) / n;
  const variance = scores.reduce((s, v) => s + (v - mean) ** 2, 0) / n;
  const stddev = Math.sqrt(variance);
  const passRate = scores.filter((v) => v >= passThreshold).length / n;
  return { mean, stddev, passRate, sampleSize: n };
}
function cohensD(a, b) {
  const pooledStddev = Math.sqrt((a.stddev ** 2 + b.stddev ** 2) / 2);
  if (pooledStddev === 0) return 0;
  return Math.abs(b.mean - a.mean) / pooledStddev;
}
function severity(d) {
  if (d >= 0.8) return "high";
  if (d >= 0.5) return "medium";
  return "low";
}
function detectDrift(metric, baselineScores, currentScores, options = {}) {
  const { effectSizeThreshold = 0.2, passThreshold = 0.7 } = options;
  const baseline = windowStats(baselineScores, passThreshold);
  const current = windowStats(currentScores, passThreshold);
  const effectSize = cohensD(baseline, current);
  const detected = effectSize >= effectSizeThreshold && current.sampleSize > 0 && baseline.sampleSize > 0;
  return {
    metric,
    detected,
    severity: severity(effectSize),
    meanShift: current.mean - baseline.mean,
    passRateChange: current.passRate - baseline.passRate,
    effectSize,
    baseline,
    current
  };
}
function detectDriftBatch(scoreMap, options = {}) {
  return Object.entries(scoreMap).map(
    ([metric, { baseline, current }]) => detectDrift(metric, baseline, current, options)
  );
}

// src/prompts/store.ts
var registeredStore = null;
function registerPromptStore(store) {
  registeredStore = store;
}
function getPromptStore() {
  return registeredStore;
}

// src/prompts/custom.ts
function readCustomPrompts() {
  return getPromptStore()?.read() ?? [];
}
function createCustomPrompt(prompt) {
  const store = getPromptStore();
  if (!store) {
    throw new EvalMetricError(
      "No prompt store registered. Custom prompts require a storage backend."
    );
  }
  const existing = store.read();
  const idx = existing.findIndex((p) => p.id === prompt.id);
  if (idx >= 0) {
    existing[idx] = prompt;
  } else {
    existing.push(prompt);
  }
  store.write(existing);
}
function deleteCustomPrompt(id) {
  const store = getPromptStore();
  if (!store) {
    throw new EvalMetricError(
      "No prompt store registered. Custom prompts require a storage backend."
    );
  }
  const existing = store.read();
  const updated = existing.filter((p) => p.id !== id);
  if (updated.length === existing.length) {
    throw new EvalMetricError(`Custom evaluator "${id}" not found`);
  }
  store.write(updated);
}

